import type { ConfigReconnect } from "@opencode-ai/core/v1/config/reconnect"

export const USAGE = "Usage: /reconnect [default | fixed <interval_ms> | retries <max_retries|default>]"
export const DEFAULT_MAX_RETRIES = 5

type Mode = { mode: "default" } | { mode: "fixed"; interval_ms: number }
type Command = { type: "show" } | { type: "mode"; value: Mode } | { type: "retries"; value: number | null }

function parse(text: string): Command | undefined {
  const args = text.trim().split(/\s+/)
  if (args[0] !== "/reconnect") return
  if (args.length === 1) return { type: "show" }
  if (args.length === 2 && args[1] === "default") return { type: "mode", value: { mode: "default" } }
  if (args.length !== 3) return
  if (args[1] === "retries" && args[2] === "default") return { type: "retries", value: null }
  if (!/^\d+$/.test(args[2])) return
  const number = Number(args[2])
  if (!Number.isSafeInteger(number) || number < 1) return
  if (args[1] === "fixed" && number <= 2_147_483_647)
    return { type: "mode", value: { mode: "fixed", interval_ms: number } }
  if (args[1] === "retries" && number <= 10_000) return { type: "retries", value: number }
}

/** One controller per backend process, shared by all local sessions and subagents. */
export function create() {
  let mode: Mode | undefined
  let retries: number | null | undefined

  function resolve(defaults?: ConfigReconnect.Info) {
    return {
      ...(mode ?? (defaults?.mode === "fixed" ? defaults : { mode: "default" as const })),
      max_retries: retries === null ? DEFAULT_MAX_RETRIES : (retries ?? defaults?.max_retries ?? DEFAULT_MAX_RETRIES),
    }
  }

  function command(text: string, defaults?: ConfigReconnect.Info) {
    const action = parse(text)
    if (!action) return { ok: false, message: USAGE }
    if (action.type === "mode") mode = action.value
    if (action.type === "retries") retries = action.value

    const current = resolve(defaults)
    const description = `mode=${current.mode === "fixed" ? `fixed every ${current.interval_ms}ms` : "default"}, max_retries=${current.max_retries}`
    return {
      ok: true,
      message:
        action.type === "show"
          ? `Reconnect settings: ${description}`
          : `Reconnect settings updated: ${description}; active until this process exits; config unchanged`,
    }
  }

  return { resolve, command }
}

