    await Effect.runPromise(
      Effect.gen(function* () {
        const runtime = Reconnect.create()
        const attempts: number[] = []
        const waits: number[] = []
        const policy = SessionRetry.policy({
          provider: "test",
          reconnect: defaults,
          runtime,
          parse: () => error,
          set: (info) =>
            Effect.sync(() => {
              attempts.push(info.attempt)
              waits.push(info.next - Date.now())
            }),
        })
        const parent = yield* Schedule.toStepWithMetadata(policy)
        const child = yield* Schedule.toStepWithMetadata(policy)
        yield* parent(error)
        runtime.command("/reconnect fixed 50", defaults)
        runtime.command("/reconnect retries 2", defaults)
        yield* parent(error)
        yield* child(error)
        const stopped = yield* Effect.exit(parent(error))
        expect(stopped._tag).toBe("Failure")
        expect(attempts).toEqual([1, 2, 1])
        expect(waits[0]).toBeGreaterThan(2900)
        expect(waits[0]).toBeLessThanOrEqual(3000)
        expect(waits.slice(1).every((wait) => wait > 0 && wait <= 50)).toBe(true)
      }),
    )
  })

  test("permits more than five retries and stops exactly at the configured budget", async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        const attempts: number[] = []
